export const defaultTerms=`1. Booking & Payment: A non-refundable deposit is required to secure the date; the balance is due before the event.
2. Cancellation: If canceled, the deposit is non-refundable; partial refunds are available depending on timing.
3. Delivery: As mentioned in the quotation.
4. Usage: Wedding Clap retains copyright; clients may use images for personal use.
5. Liability: Wedding Clap is not liable for missed shots due to factors beyond control.
6. Failure to Pay and Data Liability: If payment is not received within one month from the date of the event, we will not be responsible for the storage, retention, or recovery of any client data. It is the client's sole responsibility to ensure timely payment to avoid potential data loss.`;
export const businessDefaults={company:'Wedding Clap',address:'Maharashtra\nIndia',phone:'7517558994',email:'weddingclapp@gmail.com',signatory:'Sumit Mane',terms:defaultTerms};
export function invoiceDateFromPayments(payments,today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'})){return payments.map(p=>p.date).filter(value=>/^\d{4}-\d{2}-\d{2}$/.test(value||'')&&invoicePaymentDate(value)!=='Not recorded').sort().at(-1)||today;}
export function invoiceDraft(store,packageId){if(packageId?.startsWith('client:'))return clientInvoiceDraft(store,packageId.slice(7));const p=store.data.packages?.find(p=>p.id===packageId);if(!p)throw Error('Create or select a package first');const c=store.data.clients.find(c=>c.id===p.client),receipts=store.data.payments.filter(x=>x.package===p.id).map(x=>({...x}));if(store.data.payments.some(x=>x.client===c.id&&!x.package))throw Error('Allocate all client receipts to packages before invoicing');const es=store.data.events.filter(e=>p.events.includes(e.id)).sort((a,b)=>a.date.localeCompare(b.date)).map(e=>({id:e.id,type:e.type,date:e.date,venue:e.venue,city:e.city,start:e.start,end:e.end,timeNotRecorded:e.timeNotRecorded,services:e.services}));if(c.id==="WC-0003"&&p.invoiceReference==="003600")for(const e of es){e.services=e.type==="Wedding"?"1 Cinematographer, 1 Traditional Photographer, 1 Traditional Videographer":e.type==="Reception"?"1 Traditional Photographer":"1 Traditional Photographer, 1 Traditional Videographer";if(e.type==="Haldi")e.type="Puja & Haldi";}const paid=receipts.reduce((n,x)=>n+x.amount,0),total=p.price-p.discount;const branding=selectedBranding(store),biz={...businessDefaults,...branding.business,company:branding.business.company||store.data.settings.company};let terms=p.invoiceTerms||biz.terms;if(p.client==='WC-0003'&&p.invoiceReference==='003600'&&!p.invoiceTerms)terms=terms.replace('As mentioned in the quotation.','Edited photos are delivered within 2 weeks.').replace('within one month','within three months');if(p.client==='WC-0003'&&p.invoiceReference==='003612'&&!p.invoiceTerms)terms=terms.replace('As mentioned in the quotation.','Edited photos are delivered within 2 weeks.');if(p.invoiceReference==='003614'&&!p.invoiceTerms)terms=terms.replace('As mentioned in the quotation.','Edited photos are delivered within 1 week & Reels within 2 weeks.');return {companyId:store.companyId,theme:branding.theme,templateId:branding.templateId,client:c.id,package:p.id,billTo:p.billTo||c.name,date:invoiceDateFromPayments(receipts),termsLabel:'Due on Receipt',company:biz,packageName:p.name,price:p.price,discount:p.discount,total,paid,balance:total-paid,events:es,payments:receipts,deliverables:packageDeliverables(p),complimentary:packageDeliverables(p,'complimentary'),notes:p.invoiceNotes||'Thank you for choosing '+biz.company+'.',terms,originalReference:p.invoiceReference||''};}
export function issueInvoice(store,draft){if(!draft.billTo.trim()||!/^\d{4}-\d{2}-\d{2}$/.test(draft.date))throw Error('Enter billed-to name and invoice date');const current=invoiceDraft(store,draft.clientInvoice?'client:'+draft.client:draft.package);if(current.total!==draft.total||current.paid!==draft.paid||JSON.stringify(current.payments)!==JSON.stringify(draft.payments))throw Error('Financial data changed. Reopen invoice preview');return saveIssuedDocument(store,draft);}
export function saveIssuedDocument(store,draft){const before=structuredClone(store.data);try{const existing=JSON.parse(store.storage.getItem(store.storageKey||'wedding-clap-empty-original-v1')||'null');const used=new Set([...(store.companyId==='default'||!store.companyId?['003600','003612','003614','003621']:[]),...(store.data.invoices||[]).map(x=>x.number),...(existing?.invoices||[]).map(x=>x.number),...(store.data.deletedClients||[]).flatMap(x=>(x.invoices||[]).map(i=>i.number)),...(store.data.packages||[]).map(x=>x.invoiceReference).filter(Boolean)]);const numbering=store.data.settings.invoiceNumbering||{prefix:'',padding:6},format=n=>numbering.prefix+String(n).padStart(numbering.padding,'0');let next=Math.max(store.companyId==='default'||!store.companyId?3622:1,store.data.nextInvoice||0,existing?.nextInvoice||0,...(store.data.invoices||[]).map(i=>i.sequence||0).map(n=>n+1),...[...used].filter(n=>/^\d+$/.test(n)).map(n=>Number(n)+1));while(used.has(format(next)))next++;if(existing&&JSON.stringify(existing.payments)!==JSON.stringify(store.data.payments))throw Error('Another tab changed payments. Refresh before issuing');if(existing?.invoices?.some(x=>!(store.data.invoices||[]).some(y=>y.id===x.id)))throw Error('Another tab saved invoices. Refresh before issuing');if(draft.companyId&&draft.companyId!==store.companyId)throw Error('Document belongs to another company');const inv={...structuredClone(draft),companyId:store.companyId,sequence:next,id:crypto.randomUUID(),number:format(next),issuedAt:new Date().toISOString()};store.data.invoices ||= [];store.data.invoices.push(inv);store.data.nextInvoice=next+1;store.save();return inv;}catch(e){store.data=before;throw e;}}
export function amountWords(n){const small=['Zero','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'],tens=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];const w=v=>v<20?small[v]:v<100?tens[Math.floor(v/10)]+(v%10?' '+w(v%10):''):v<1000?w(Math.floor(v/100))+' Hundred'+(v%100?' '+w(v%100):''):v<100000?w(Math.floor(v/1000))+' Thousand'+(v%1000?' '+w(v%1000):''):v<10000000?w(Math.floor(v/100000))+' Lakh'+(v%100000?' '+w(v%100000):''):w(Math.floor(v/10000000))+' Crore'+(v%10000000?' '+w(v%10000000):'');return 'Indian Rupees '+w(Math.floor(n))+(Math.round((n%1)*100)?' and '+w(Math.round((n%1)*100))+' Paise':'')+' Only';}
export function invoicePaymentDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return 'Not recorded';const d=new Date(value+'T12:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==value)return 'Not recorded';return d.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kolkata'});}
export function invoicePaymentLabel(payment,label){const date=invoicePaymentDate(payment.date);if(!label)return (payment.stage||'Payment')+' · '+date+' · '+(payment.method||'Not set');const parts=String(label).split(' · ');if(parts.length>=3&&/^(?:\d{4}-\d{2}-\d{2}|\d{1,2} [A-Za-z]+ \d{4}|Not set|Not recorded|Date unknown|Invalid Date)$/.test(parts[1]))parts[1]=date;else return label+' · Payment date: '+date;return parts.join(' · ');}
export function receiptTheme(inv){const theme=inv.theme||{};return inv.companyId==='default'?{...theme,signatureImage:theme.signatureImage||originalReceiptAssets.signatureImage}:theme;}
