export function hydrateInvoicePackages(data){for(const p of data.packages||[]){const c=data.clients.find(c=>c.id===p.client);if(!c)continue;let items,extra=[];if(p.client==='WC-0003'&&p.invoiceReference==='003612'){items=['2 cinematic reels (30–60 seconds each)','40–50 selected images for editing & color grading','5 countdown images','All raw data photos'];p.billTo ||= 'Mr. Keyur Trivedi';}else if(p.client==='WC-0003'&&p.invoiceReference==='003600'){items=['Unlimited raw data photos','Cinematic teaser (1 minute), highlight (3–5 minutes)','Traditional full-length video (1–3 hours) per day','1 photobook album (250 selected photos)','2 cinematic reels'];extra=['1 minibook album','1 digital invitation','1 pendrive'];p.billTo ||= 'Mr. Keyur Trivedi';}else if(p.client==='WC-0002'&&(p.legacy||p.invoiceReference==='003614')&&/nitin/i.test(c.name)){items=['Unlimited raw data photos — Google Drive link','40–50 edited images (minimum)','2 cinematic reels (30–50 seconds each)','5 countdown images'];p.billTo ||= 'Nitin Sawarn';p.invoiceReference ||= '003614';}else if(/vandana.*shakya/i.test(c.name)&&(p.legacy||p.invoiceReference==='003621')){items=['Digital photo invitation','All raw photos','Cinematic teaser — 1 minute','Traditional video — 30 minutes–1 hour (depending on event flow)','2 cinematic reels — 30–40 seconds each','50–60 edited images','Album — 100–120 selected images'];p.billTo ||= 'Ms. Vandana Shakya';p.invoiceReference ||= '003621';}if(items){p.deliverables ??= items;p.complimentary ??= extra;}}}

function clientInvoiceDraft(store,id){const c=store.data.clients.find(c=>c.id===id);if(!c)throw Error('Client not found');const brand=selectedBranding(store),company={...businessDefaults,...brand.business,company:brand.business.company||store.data.settings.company},total=store.quote(id),discount=Number(c.discount||0),payments=store.data.payments.filter(p=>p.client===id).map(p=>({...p})),paid=store.paid(id),nitin=store.companyId==='default'&&id==='WC-0002'&&/nitin/i.test(c.name);return {clientInvoice:true,companyId:store.companyId,client:id,package:'',theme:brand.theme,templateId:brand.templateId,company,billTo:nitin?'Nitin Sawarn':c.name,date:invoiceDateFromPayments(payments),termsLabel:'Due on Receipt',packageName:nitin?'Pre-Wedding':c.package||'Photography booking',price:total+discount,discount,total,paid,balance:total-paid,payments,events:store.data.events.filter(e=>e.client===id).map(e=>({...e})),deliverables:nitin?['Unlimited raw data photos – Google Drive link','40–50 edited images (minimum)','2 cinematic reels (30–50 seconds each)','5 countdown images']:[],complimentary:[],notes:'Thank you for choosing '+company.company+'.',terms:nitin?company.terms.replace('As mentioned in the quotation.','Edited photos are delivered within 1 week & Reels within 2 weeks.'):company.terms,description:nitin?'Duration of shoot: 6–8 hours\nLocations & outfit changes: 3 locations + 3 outfit changes':'',referenceWarning:nitin&&paid!==9000?'Original invoice 003614 shows ₹9,000 received and ₹1,000 outstanding. This app currently shows '+paid+' received. Verify payment history before issuing.':''};}
